__global__ void matmul_2x3_3x2(const float* left, const float* right, float* product, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) {
    return;
  }
  int row = i / 2;
  int col = i % 2;
  float sum = 0.0f;
  for (int k = 0; k < 3; k++) {
    sum += left[row * 3 + k] * right[k * 2 + col];
  }
  product[i] = sum;
}
